        "content":  ":root {
  --bg-color: #f4f6f1; /* Hueso/crema claro */
  --card-bg: #ffffff;
  --text-main: #111827;
  --text-muted: #6b7280;
  --text-light: #9ca3af;

  /* Brand colors */
  --accent-orange: #ff6b6b;
  --accent-orange-light: #ffe5e5;
  --accent-green: #4ade80;
  --accent-green-light: #dcfce7;
  --accent-green-text: #166534;
  --accent-dark: #1f2937; /* For primary buttons */
  --border-color: #f3f4f6;
  --sidebar-active-bg: #d3f36b; /* Lima/verde claro del active state */
  --sidebar-active-text: #1a202c;

  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-xl: 32px;

  --shadow-soft: 0 8px 30px rgba(0, 0, 0, 0.03);
  --shadow-card: 0 4px 20px rgba(0, 0, 0, 0.02);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  -webkit-font-smoothing: antialiased;
}

/* Typography Utilities */
.text-h1 { font-size: 24px; font-weight: 600; }
.text-h2 { font-size: 18px; font-weight: 600; }
.text-h3 { font-size: 16px; font-weight: 500; }
.text-body { font-size: 14px; font-weight: 400; }
.text-small { font-size: 12px; font-weight: 500; }

.text-muted { color: var(--text-muted); }
.font-medium { font-weight: 500; }
.font-semibold { font-weight: 600; }

/* Flex Utilities */
.flex { display: flex; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-2 { gap: 8px; }
.gap-4 { gap: 16px; }
.gap-6 { gap: 24px; }
.flex-col { flex-direction: column; }

/* App Layout */
.app-container {
  display: flex;
  min-height: 100vh;
  padding: 24px;
  gap: 24px;
  max-width: 1600px;
  margin: 0 auto;
}

/* Sidebar */
.sidebar {
  width: 250px;
  background: var(--card-bg);
  border-radius: var(--radius-xl);
  padding: 24px;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-card);
  flex-shrink: 0;
}

.sidebar-logo {
  font-size: 24px;
  font-weight: 700;
  color: var(--accent-dark);
  margin-bottom: 32px;
}

.sidebar-workspace {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border-radius: var(--radius-md);
  margin-bottom: 24px;
  cursor: pointer;
}

.workspace-icon {
  width: 32px;
  height: 32px;
  background: var(--bg-color);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border-radius: var(--radius-lg);
  color: var(--text-muted);
  text-decoration: none;
  font-weight: 500;
  font-size: 15px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.nav-item:hover {
  background: var(--bg-color);
  color: var(--text-main);
}

.nav-item.active {
  background: var(--sidebar-active-bg);
  color: var(--sidebar-active-text);
}

/* Main Content */
.main-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* Header */
.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--card-bg);
  padding: 16px 24px;
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-card);
}

.search-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-color);
  padding: 8px 16px;
  border-radius: var(--radius-lg);
  width: 300px;
}

.search-bar input {
  border: none;
  background: none;
  outline: none;
  width: 100%;
  font-family: inherit;
  font-size: 14px;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.icon-btn {
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--bg-color);
  transition: all 0.2s;
}

.icon-btn:hover {
  background: #e5e7eb;
  color: var(--text-main);
}

.user-profile {
  display: flex;
  align-items: center;
  gap: 12px;
}

.avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
}

/* Welcome Section */
.welcome-section {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-top: 8px;
}

.btn-primary {
  background: var(--accent-dark);
  color: white;
  border: none;
  padding: 12px 24px;
  border-radius: var(--radius-lg);
  font-weight: 500;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: inherit;
}

/* Dashboard Grid */
.dashboard-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 24px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius-xl);
  padding: 24px;
  box-shadow: var(--shadow-card);
}

/* KPI Cards */
.kpi-container {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.kpi-card {
  padding: 20px;
  border-right: 1px solid var(--border-color);
}
.kpi-card:last-child {
  border-right: none;
}

.kpi-label {
  color: var(--text-muted);
  font-size: 13px;
  font-weight: 500;
  margin-bottom: 8px;
}

.kpi-value {
  font-size: 28px;
  font-weight: 600;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 12px;
}

.kpi-trend {
  font-size: 11px;
  padding: 4px 8px;
  border-radius: 20px;
  font-weight: 600;
}
.kpi-trend.positive {
  background: var(--accent-green-light);
  color: var(--accent-green-text);
}
.kpi-trend.negative {
  background: var(--accent-orange-light);
  color: var(--accent-orange);
}

/* Chart Styles */
.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.recharts-cartesian-grid-horizontal line,
.recharts-cartesian-grid-vertical line {
  stroke: var(--border-color);
}

.recharts-tooltip-wrapper {
  outline: none;
}
.custom-tooltip {
  background: var(--card-bg);
  border-radius: var(--radius-md);
  padding: 12px;
  box-shadow: var(--shadow-soft);
  border: 1px solid var(--border-color);
}

/* List Styles */
.list-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px;
  border-radius: var(--radius-lg);
  background: var(--bg-color);
  margin-bottom: 12px;
}

.status-badge {
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
}
.status-won {
  background: var(--accent-green-light);
  color: var(--accent-green-text);
}
.status-open {
  background: #e0e7ff;
  color: #3730a3;
}
.status-lost {
  background: var(--accent-orange-light);
  color: var(--accent-orange);
}
