import React, { useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

export default function PipelineChart({ deals, stages }) {

  const data = useMemo(() => {
    // Group amount by stage
    const grouped = stages.map(stage => {
      const stageDeals = deals.filter(d => d.stage_id === stage.id);
      const totalAmount = stageDeals.reduce((sum, d) => sum + d.amount, 0);
      return {
        name: stage.name,
        value: totalAmount,
        originalStage: stage
      };
    });
    return grouped;
  }, [deals, stages]);

  const formatCurrency = (value) => `Bs ${(value / 1000).toFixed(0)}k`;

  return (
    <div style={{ height: 300, width: '100%', marginTop: '20px' }}>
      <ResponsiveContainer width="100%" height="100%">
        <BarChart
          data={data}
          margin={{ top: 20, right: 30, left: 20, bottom: 5 }}
          barSize={40}
        >
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="var(--border-color)" />
          <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: 'var(--text-muted)', fontSize: 12 }} dy={10} />
          <YAxis tickFormatter={formatCurrency} axisLine={false} tickLine={false} tick={{ fill: 'var(--text-muted)', fontSize: 12 }} />
          <Tooltip 
            cursor={{fill: 'var(--bg-color)'}}
            contentStyle={{ borderRadius: '8px', border: '1px solid var(--border-color)', boxShadow: 'var(--shadow-soft)', backgroundColor: 'var(--card-bg)', color: 'var(--text-main)' }}
            formatter={(value) => [`Bs ${value.toLocaleString('es-BO')}`, 'Valor']}
          />
          <Bar dataKey="value" radius={[6, 6, 6, 6]}>
            {data.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={entry.name === 'Agendado' ? '#1CA9C9' : '#1E4C9A'} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

import React, { useMemo } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

export default function SalesTrendChart({ deals }) {
  const data = useMemo(() => {
    const wonDeals = deals.filter(d => d.status === 'won');

    // Group by month
    const monthlyData = wonDeals.reduce((acc, deal) => {
      const date = new Date(deal.closed_at || deal.created_at);
      const month = date.toLocaleString('es-ES', { month: 'short' });

      // capitalize first letter
      const monthCapitalized = month.charAt(0).toUpperCase() + month.slice(1);

      if (!acc[monthCapitalized]) {
        acc[monthCapitalized] = { name: monthCapitalized, revenue: 0 };
      }
      acc[monthCapitalized].revenue += deal.amount;
      return acc;
    }, {});

    // Sort months
    const monthsOrder = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];
    return Object.values(monthlyData).sort((a, b) => {
      return monthsOrder.indexOf(a.name) - monthsOrder.indexOf(b.name);
    });
  }, [deals]);

  const formatCurrency = (value) => `Bs ${(value / 1000).toFixed(0)}k`;

  return (
    <div style={{ height: 300, width: '100%', marginTop: '20px' }}>
      <ResponsiveContainer width="100%" height="100%">
        <AreaChart
          data={data}
          margin={{ top: 10, right: 30, left: 0, bottom: 0 }}
        >
          <defs>
            <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="#1CA9C9" stopOpacity={0.4}/>
              <stop offset="95%" stopColor="#1CA9C9" stopOpacity={0}/>
            </linearGradient>
          </defs>
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="var(--border-color)" />
          <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: 'var(--text-muted)', fontSize: 12 }} dy={10} />
          <YAxis tickFormatter={formatCurrency} axisLine={false} tickLine={false} tick={{ fill: 'var(--text-muted)', fontSize: 12 }} />
          <Tooltip 
            contentStyle={{ borderRadius: '8px', border: '1px solid var(--border-color)', boxShadow: 'var(--shadow-soft)', backgroundColor: 'var(--card-bg)', color: 'var(--text-main)' }}
            formatter={(value) => [`Bs ${value.toLocaleString('es-BO')}`, 'Ingresos']}
          />
          <Area type="monotone" dataKey="revenue" stroke="#1CA9C9" strokeWidth={3} fillOpacity={1} fill="url(#colorRevenue)" />
        </AreaChart>
      </ResponsiveContainer>
    </div>
  );
}

import React from 'react';
import { customers } from '../data/mockData';

export default function TopDeals({ deals }) {
  // Sort open deals by amount descending, get top 4
  const topDeals = [...deals]
    .filter(d => d.status === 'open')
    .sort((a, b) => b.amount - a.amount)
    .slice(0, 4);

  const getCustomerName = (id) => {
    return customers.find(c => c.id === id)?.company_name || 'Desconocido';
  };

  const formatCurrency = (value) => {
    return new Intl.NumberFormat('es-BO', {
      style: 'currency',
      currency: 'BOB',
      maximumFractionDigits: 0
    }).format(value);
  };

  return (
    <div style={{ marginTop: '16px' }}>
      {topDeals.map((deal) => (
        <div key={deal.id} className="list-item">
          <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
            <div style={{ 
              width: '40px', 
              height: '40px', 
              borderRadius: '8px', 
              background: '#e0f7fa', 
              display: 'flex', 
              alignItems: 'center', 
              justifyContent: 'center',
              fontWeight: '600',
              color: '#00838f'
            }}>
              {getCustomerName(deal.customer_id).charAt(0)}
            </div>
            <div>
              <div className="text-small font-semibold">{deal.title}</div>
              <div className="text-small text-muted">{getCustomerName(deal.customer_id)}</div>
            </div>
          </div>
          <div style={{ textAlign: 'right' }}>
            <div className="text-small font-semibold">{formatCurrency(deal.amount)}</div>
            <div className="status-badge status-open" style={{ display: 'inline-block', marginTop: '4px' }}>
              Pendiente
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

